<?php
declare(strict_types=1);
const CMS_ROOT = __DIR__ . '/..';
const CMS_DATA = __DIR__ . '/private';
const CMS_GUARD = "<?php http_response_code(404); exit; ?>\n";
final class CmsError extends RuntimeException { public int $status; public function __construct(string $message, int $status = 400) { parent::__construct($message); $this->status = $status; } }
function fail(string $message, int $status = 400): void { throw new CmsError($message, $status); }
function ensure_dirs(): void { foreach (['', '/drafts', '/revisions', '/trash', '/limits', '/sessions'] as $part) if (!is_dir(CMS_DATA . $part) && !@mkdir(CMS_DATA . $part, 0700, true)) fail('The admin storage folder is not writable. Check its permissions in Hostinger.', 500); }
function atomic_write(string $path, string $content, int $mode = 0644): void { $temp = dirname($path) . '/.ncc-' . bin2hex(random_bytes(8)) . '.php'; if (@file_put_contents($temp, $content, LOCK_EX) === false) fail('Could not save the file. Check the hosting folder permissions.', 500); @chmod($temp, $mode); if (!@rename($temp, $path)) { @unlink($temp); fail('Could not finish saving the file.', 500); } }
function load_data(string $path, $default = []) { if (!is_file($path)) return $default; $raw = file_get_contents($path); if (strpos($raw, CMS_GUARD) !== 0) fail('The admin data file could not be read.', 500); $data = json_decode(substr($raw, strlen(CMS_GUARD)), true); if (json_last_error() !== JSON_ERROR_NONE) fail('The admin data file is damaged. Restore it from a backup.', 500); return $data; }
function credential_key(): string {
 if (!function_exists('openssl_encrypt')) fail('Enable the PHP OpenSSL extension for encrypted owner storage.',500);
 $path=CMS_DATA.'/encryption-key.php';
 $record=load_data($path);
 if (!$record) { $record=['key'=>base64_encode(random_bytes(32))]; save_data($path,$record); }
 $key=base64_decode($record['key']??'',true);
 if ($key===false || strlen($key)!==32) fail('The owner encryption key is missing or damaged. Restore it from your backup.',500);
 return $key;
}
function save_data(string $path, $data): void {
 if ($path===CMS_DATA.'/account.php' && isset($data['username'])) {
  $iv=random_bytes(12);$tag='';
  $encrypted=openssl_encrypt($data['username'],'aes-256-gcm',credential_key(),OPENSSL_RAW_DATA,$iv,$tag,'ncc-owner-v1');
  if ($encrypted===false) fail('Could not encrypt the owner login.',500);
  $data['username_encrypted']=['cipher'=>'aes-256-gcm','iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'value'=>base64_encode($encrypted)];
  unset($data['username']);
 }
 atomic_write($path, CMS_GUARD . json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR), 0600);
}
function locked(callable $fn) { ensure_dirs(); $handle = fopen(CMS_DATA . '/write-lock.php', 'c+'); if (!$handle || !flock($handle, LOCK_EX)) fail('The website is busy. Please try again.', 503); try { return $fn(); } finally { flock($handle, LOCK_UN); fclose($handle); } }
function session_boot(): void { ini_set('session.use_strict_mode', '1'); ini_set('session.use_only_cookies', '1'); session_save_path(CMS_DATA . '/sessions'); session_name('ncc_admin'); $path = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/admin/api.php')), '/') ?: '/admin'; session_set_cookie_params(['lifetime' => 0, 'path' => $path . '/', 'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off', 'httponly' => true, 'samesite' => 'Strict']); if (!@session_start()) fail('The admin session could not start. Check the private storage folder permissions.', 500); if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32)); if (isset($_SESSION['last']) && time() - (int)$_SESSION['last'] > 3600) { unset($_SESSION['user']); $_SESSION['csrf'] = bin2hex(random_bytes(32)); } }
function user_record(): array {
 $account=load_data(CMS_DATA.'/account.php');
 if (!$account) return [];
 if (isset($account['username_encrypted'])) {
  $e=$account['username_encrypted'];$keyPath=CMS_DATA.'/encryption-key.php';
  if(!is_file($keyPath))fail('The owner encryption key is missing. Restore it from your backup.',500);
  $username=openssl_decrypt(base64_decode($e['value'],true),'aes-256-gcm',credential_key(),OPENSSL_RAW_DATA,base64_decode($e['iv'],true),base64_decode($e['tag'],true),'ncc-owner-v1');
  if($username===false)fail('The owner login could not be decrypted. Restore the matching account and key from backup.',500);
  $account['username']=$username;
 }
 return $account;
}
function require_auth(): void { $account = user_record(); if (empty($_SESSION['user']) || empty($account['username']) || !hash_equals($account['username'], $_SESSION['user'])) fail('Please sign in to continue.', 401); $_SESSION['last'] = time(); }
function protect_post(): void { $token = $_SERVER['HTTP_X_CSRF_TOKEN'] ?? ''; if (!is_string($token) || !hash_equals($_SESSION['csrf'], $token)) fail('Your session changed. Refresh the page and try again.', 403); if (($_SERVER['HTTP_SEC_FETCH_SITE'] ?? '') === 'cross-site') fail('Please send this request from the admin console.', 403); $origin = $_SERVER['HTTP_ORIGIN'] ?? ''; if ($origin !== '') { $a = parse_url($origin, PHP_URL_HOST); $b = parse_url('https://' . ($_SERVER['HTTP_HOST'] ?? ''), PHP_URL_HOST); if (!$a || !$b || strcasecmp($a, $b) !== 0) fail('This request came from a different website.', 403); } }
function rate_limit(string $group, int $max = 8): void { $key = hash('sha256', $group . '|' . ($_SERVER['REMOTE_ADDR'] ?? '') . '|' . __DIR__); $file = CMS_DATA . '/limits/' . $key . '.php'; locked(function () use ($file, $max) { $r = load_data($file, ['start' => time(), 'count' => 0]); if (time() - (int)$r['start'] >= 900) $r = ['start' => time(), 'count' => 0]; if ($r['count'] >= $max) fail('Too many attempts. Please wait 15 minutes before trying again.', 429); $r['count']++; save_data($file, $r); }); }
function slug(string $value): string { if (!preg_match('/^[a-z][a-z0-9-]{0,63}$/D', $value)) fail('Use a page address with lowercase letters, numbers and hyphens.'); return $value; }
function page_file(string $name): string { return CMS_ROOT . '/' . slug($name) . '.html'; }
function password_value(array $data, string $key): string { $v=$data[$key]??''; if(!is_string($v)||strlen($v)>72) fail('Use a password no longer than 72 bytes.'); return $v; }
function text_value(array $data, string $key, int $max = 300, string $default = ''): string { $value = $data[$key] ?? $default; if (!is_string($value) || strlen($value) > $max) fail('Please check the ' . str_replace('_', ' ', $key) . ' field.'); return trim($value); }
function document_from(string $html): DOMDocument { if (strlen($html) > 2000000) fail('The page is too large. Use the Media Library for pictures.'); if (!class_exists('DOMDocument')) fail('Enable the PHP DOM extension in Hostinger to use the editor.', 500); $doc = new DOMDocument('1.0', 'UTF-8'); $previous = libxml_use_internal_errors(true); $ok = $doc->loadHTML('<?xml encoding="UTF-8">' . $html, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING); libxml_clear_errors(); libxml_use_internal_errors($previous); if (!$ok) fail('The page HTML could not be read.'); foreach (iterator_to_array($doc->childNodes) as $node) if ($node->nodeType === XML_PI_NODE) $doc->removeChild($node); return $doc; }
function serialize_doc(DOMDocument $doc): string { return $doc->saveHTML(); }
function safe_url(string $url, bool $image = false): bool { $url = trim(html_entity_decode($url, ENT_QUOTES | ENT_HTML5, 'UTF-8')); if ($url === '') return true; if (preg_match('/[\x00-\x20\\\\<>]/', $url) || strpos($url, '//') === 0) return false; $scheme = parse_url($url, PHP_URL_SCHEME); if ($scheme && !in_array(strtolower($scheme), $image ? ['http', 'https'] : ['http', 'https', 'mailto', 'tel'], true)) return false; return !preg_match('~(^|/)\.\.(/|$)~', $url); }
function clean_style(string $style): string { $allowed = ['color','background-color','font-size','font-weight','font-style','font-family','text-align','text-decoration','line-height','letter-spacing','padding','padding-top','padding-right','padding-bottom','padding-left','margin','margin-top','margin-right','margin-bottom','margin-left','width','max-width','min-width','height','min-height','max-height','object-fit','object-position','display','border-radius','border','border-color','border-width','border-style','gap','grid-template-columns','align-items','justify-content','opacity']; $out = []; foreach (explode(';', $style) as $pair) { $parts = explode(':', $pair, 2); if (count($parts) !== 2) continue; $key = strtolower(trim($parts[0])); $value = trim($parts[1]); if (in_array($key, $allowed, true) && !preg_match('/url\s*\(|expression|@|javascript|[<>\\\\]/i', $value) && strlen($value) < 200) $out[] = $key . ':' . $value; } return implode(';', $out); }
function sanitize_page(string $html): string { $doc = document_from($html); $allowed = explode(' ', 'html head title meta link body header footer main section article aside nav div span p h1 h2 h3 h4 h5 h6 a strong em b i u s strike small sub sup mark blockquote pre code br hr ul ol li figure figcaption img picture source table thead tbody tfoot tr th td caption colgroup col form label input textarea select option optgroup button details summary dl dt dd time address'); $elements = iterator_to_array($doc->getElementsByTagName('*')); foreach ($elements as $el) { $tag = strtolower($el->tagName); if ($tag === 'script') { if ($el->getAttribute('src') === 'assets/app.js') { foreach (iterator_to_array($el->attributes) as $attribute) $el->removeAttribute($attribute->name); $el->setAttribute('src','assets/app.js'); $el->setAttribute('defer',''); while ($el->firstChild) $el->removeChild($el->firstChild); } else if ($el->parentNode) $el->parentNode->removeChild($el); continue; } if (!in_array($tag, $allowed, true)) { if ($el->parentNode) $el->parentNode->removeChild($el); continue; } if ($tag === 'meta' && $el->hasAttribute('http-equiv')) { $el->parentNode->removeChild($el); continue; } foreach (iterator_to_array($el->attributes) as $attr) { $name = strtolower($attr->name); $value = $attr->value; if (strpos($name, 'on') === 0 || in_array($name, ['srcdoc','formaction','contenteditable','spellcheck','nonce','integrity'], true) || strpos($name, 'data-cms-') === 0) { $el->removeAttribute($name); continue; } if ($name === 'style') { $style = clean_style($value); $style === '' ? $el->removeAttribute('style') : $el->setAttribute('style',$style); } if (in_array($name,['href','src','action','poster'],true) && !safe_url($value, $name === 'src' || $name === 'poster')) $el->removeAttribute($name); if ($name === 'srcset') $el->removeAttribute($name); if ($name === 'target' && $value === '_blank') $el->setAttribute('rel','noopener noreferrer'); } if ($tag === 'link' && $el->getAttribute('rel') === 'stylesheet' && !preg_match('~^assets/[a-zA-Z0-9/_-]+\.css$~D',$el->getAttribute('href'))) $el->parentNode->removeChild($el); if ($tag === 'form') { $el->setAttribute('action','contact.php'); $el->setAttribute('method','post'); } }
 if ($doc->getElementsByTagName('main')->length !== 1) fail('Keep one main content area on the page.'); if ($doc->getElementsByTagName('h1')->length !== 1) fail('Keep exactly one main heading (H1) on the page.'); return serialize_doc($doc); }
function page_title(string $html): string { $doc = document_from($html); $title = $doc->getElementsByTagName('title')->item(0); return $title ? trim(preg_replace('/\s*\|\s*Next Chapter Collective\s*$/u','',$title->textContent)) : 'Untitled page'; }
function pages_list(): array { $pages=[]; foreach (glob(CMS_ROOT . '/*.html') ?: [] as $file) { $name=basename($file,'.html'); if (!preg_match('/^[a-z][a-z0-9-]{0,63}$/D',$name)) continue; $html=file_get_contents($file); $draft=load_data(CMS_DATA.'/drafts/'.$name.'.php'); $pages[$name]=['slug'=>$name,'title'=>page_title($html),'status'=>'published','hasDraft'=>!empty($draft),'updated'=>gmdate('c',filemtime($file)),'revision'=>hash('sha256',$html)]; } foreach (glob(CMS_DATA.'/drafts/*.php') ?: [] as $file) { $draft=load_data($file); $name=$draft['slug']??''; if (!$name || isset($pages[$name])) continue; $pages[$name]=['slug'=>$name,'title'=>$draft['title'],'status'=>'draft','hasDraft'=>true,'updated'=>$draft['updated'],'revision'=>'']; } return array_values($pages); }
function page_get(string $name): array { $name=slug($name); $file=page_file($name); $draft=load_data(CMS_DATA.'/drafts/'.$name.'.php'); $published=is_file($file)?file_get_contents($file):''; if (!$draft && $published==='') fail('This page was not found.',404); return ['slug'=>$name,'title'=>$draft['title']??page_title($published),'html'=>$draft['html']??$published,'revision'=>$draft['base_revision']??hash('sha256',$published),'draft_revision'=>$draft?hash('sha256',$draft['html']):'','sharedHeader'=>$draft['sharedHeader']??false,'sharedFooter'=>$draft['sharedFooter']??false,'hasDraft'=>!empty($draft),'published'=>($published!==''),'updated'=>$draft['updated']??gmdate('c',filemtime($file))]; }
function revision_add(string $name,string $html): void { if ($html==='') return; $dir=CMS_DATA.'/revisions/'.slug($name); if (!is_dir($dir)) mkdir($dir,0700,true); $id=gmdate('Ymd-His').'-'.bin2hex(random_bytes(3)); save_data($dir.'/'.$id.'.php',['id'=>$id,'html'=>$html,'updated'=>gmdate('c'),'title'=>page_title($html)]); $files=glob($dir.'/*.php')?:[]; rsort($files); foreach(array_slice($files,20) as $file) @unlink($file); }
function revision_list(string $name): array { $out=[];foreach(glob(CMS_DATA.'/revisions/'.slug($name).'/*.php')?:[] as $file){$r=load_data($file);unset($r['html']);$out[]=$r;}usort($out,fn($a,$b)=>strcmp($b['id'],$a['id']));return $out; }
function replace_shared(string $target,string $source,bool $header,bool $footer): string { $to=document_from($target);$from=document_from($source);$xpTo=new DOMXPath($to);$xpFrom=new DOMXPath($from);$queries=[];if($header){$queries[]='//header[contains(concat(" ",normalize-space(@class)," ")," site-header ")]';$queries[]='//*[contains(concat(" ",normalize-space(@class)," ")," utility-bar ")]';}if($footer)$queries[]='//footer';foreach($queries as $query){$a=$xpTo->query($query)->item(0);$b=$xpFrom->query($query)->item(0);if($a&&$b)$a->parentNode->replaceChild($to->importNode($b,true),$a);elseif($a&&!$b)$a->parentNode->removeChild($a);}
