function write_transaction(array $updates): void { $before=[];foreach($updates as $name=>$html){$file=page_file($name);$before[$name]=is_file($file)?file_get_contents($file):null;if($before[$name]!==null)revision_add($name,$before[$name]);}try{foreach($updates as $name=>$html)atomic_write(page_file($name),$html);}catch(Throwable $e){foreach($before as $name=>$html){if($html===null)@unlink(page_file($name));else atomic_write(page_file($name),$html);}throw $e;} }
function publish_page(array $input): array { return locked(function() use($input){$name=slug(text_value($input,'slug',64));$html=sanitize_page(text_value($input,'html',2000000));$file=page_file($name);$current=is_file($file)?file_get_contents($file):'';$expected=text_value($input,'revision',64);$actual=$current!==''?hash('sha256',$current):'';if(!hash_equals($actual,$expected))fail('This page changed since you opened it. Save your draft, reopen the latest page and review before publishing.',409);$updates=[$name=>$html];$header=($input['sharedHeader']??false)===true;$footer=($input['sharedFooter']??false)===true;if($header||$footer)foreach(pages_list() as $page){if($page['slug']===$name||$page['status']!=='published')continue;$updates[$page['slug']]=replace_shared(file_get_contents(page_file($page['slug'])),$html,$header,$footer);}write_transaction($updates);@unlink(CMS_DATA.'/drafts/'.$name.'.php');return ['page'=>page_get($name),'pages'=>pages_list(),'updatedPages'=>count($updates)];}); }
function draft_save(array $input): array {return locked(function()use($input){$name=slug(text_value($input,'slug',64));$html=sanitize_page(text_value($input,'html',2000000));$file=CMS_DATA.'/drafts/'.$name.'.php';$existing=load_data($file);if($existing && !hash_equals(hash('sha256',$existing['html']),text_value($input,'draft_revision',64)))fail('A newer draft is already saved. Reopen the page before replacing it.',409);save_data($file,['slug'=>$name,'title'=>page_title($html),'html'=>$html,'base_revision'=>text_value($input,'revision',64),'sharedHeader'=>($input['sharedHeader']??false)===true,'sharedFooter'=>($input['sharedFooter']??false)===true,'updated'=>gmdate('c')]);return ['page'=>page_get($name),'pages'=>pages_list()];});}
function new_page(array $input): array {return locked(function()use($input){$name=slug(text_value($input,'slug',64));$title=text_value($input,'title',200);if($title==='')fail('Give the page a title.');if(is_file(page_file($name))||is_file(CMS_DATA.'/drafts/'.$name.'.php'))fail('That page address is already in use.',409);$doc=document_from(file_get_contents(page_file('index')));$main=$doc->getElementsByTagName('main')->item(0);while($main->firstChild)$main->removeChild($main->firstChild);$section=$doc->createElement('section');$section->setAttribute('class','section container');$h=$doc->createElement('h1');$h->appendChild($doc->createTextNode($title));$section->appendChild($h);$p=$doc->createElement('p');$p->appendChild($doc->createTextNode('Add your page content here.'));$section->appendChild($p);$main->appendChild($section);$t=$doc->getElementsByTagName('title')->item(0);$t->nodeValue=$title.' | Next Chapter Collective';$html=serialize_doc($doc);save_data(CMS_DATA.'/drafts/'.$name.'.php',['slug'=>$name,'title'=>$title,'html'=>$html,'base_revision'=>'','updated'=>gmdate('c')]);return ['page'=>page_get($name),'pages'=>pages_list()];});}
function media_list(): array {$out=[];foreach(['assets/images','assets/uploads'] as $dir)foreach(glob(CMS_ROOT.'/'.$dir.'/*')?:[] as $file){if(!is_file($file)||!preg_match('/\.(png|jpe?g|webp|gif)$/i',$file))continue;$size=@getimagesize($file);if(!$size)continue;$out[]=['url'=>$dir.'/'.basename($file),'name'=>basename($file),'width'=>$size[0],'height'=>$size[1],'bytes'=>filesize($file),'updated'=>gmdate('c',filemtime($file))];}return array_reverse($out);}
function media_upload(): array {if(empty($_FILES['image'])||!is_array($_FILES['image'])||($_FILES['image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)fail('Choose an image to upload. The server may also have a lower upload limit.');$file=$_FILES['image'];if($file['size']>10*1024*1024)fail('Choose an image smaller than 10 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($extensions[$mime]))fail('Upload a JPG, PNG, WebP or GIF image.');$size=@getimagesize($file['tmp_name']);if(!$size||$size[0]>10000||$size[1]>10000||$size[0]*$size[1]>40000000)fail('Choose an image with dimensions below 10,000 pixels and 40 megapixels.');$base=substr(trim(preg_replace('/[^a-z0-9-]+/','-',strtolower(pathinfo($file['name'],PATHINFO_FILENAME))),'-'),0,55)?:'image';$name=$base.'-'.bin2hex(random_bytes(5)).'.'.$extensions[$mime];$dir=CMS_ROOT.'/assets/uploads';if(!is_dir($dir))mkdir($dir,0755,true);if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))fail('The uploads folder is not writable.',500);chmod($dir.'/'.$name,0644);return ['media'=>media_list(),'url'=>'assets/uploads/'.$name];}
function menu_nodes(DOMDocument $doc,array $items,int $depth=0): array {if($depth>1||count($items)>30)fail('Keep the menu to two levels and no more than 30 items.');$nodes=[];foreach($items as $item){if(!is_array($item))fail('Invalid menu item.');$label=text_value($item,'label',120);if($label==='')fail('Every menu item needs a label.');$children=$item['children']??[];if($children){if($depth>0||!is_array($children))fail('Menu dropdowns can have one level of links.');$details=$doc->createElement('details');$details->setAttribute('class','nav-group');$summary=$doc->createElement('summary');$summary->appendChild($doc->createTextNode($label.' '));$span=$doc->createElement('span','⌄');$span->setAttribute('aria-hidden','true');$summary->appendChild($span);$details->appendChild($summary);$panel=$doc->createElement('div');$panel->setAttribute('class','nav-panel');foreach(menu_nodes($doc,$children,$depth+1) as $node)$panel->appendChild($node);$details->appendChild($panel);$nodes[]=$details;}else{$url=text_value($item,'url',1000);if($url===''||!safe_url($url))fail('Use a valid website address for each menu link.');$a=$doc->createElement('a');$a->setAttribute('href',$url);if(!empty($item['button']))$a->setAttribute('class','button button-dark nav-cta');if($depth>0){$strong=$doc->createElement('strong');$strong->appendChild($doc->createTextNode($label));$a->appendChild($strong);$desc=text_value($item,'description',200);if($desc!==''){$span=$doc->createElement('span');$span->appendChild($doc->createTextNode($desc));$a->appendChild($span);}}else{$a->appendChild($doc->createTextNode($label));}if(!empty($item['newTab'])){$a->setAttribute('target','_blank');$a->setAttribute('rel','noopener noreferrer');}$nodes[]=$a;}}return $nodes;}
function menu_save(array $input): array {return locked(function()use($input){$file=page_file('index');$html=file_get_contents($file);if(!hash_equals(hash('sha256',$html),text_value($input,'revision',64)))fail('The website changed. Refresh Menus before saving.',409);$doc=document_from($html);$xp=new DOMXPath($doc);$nav=$xp->query('//*[@id="navigation"]')->item(0);if(!$nav)fail('The primary menu was not found.');$items=$input['items']??[];if(!is_array($items)||!count($items))fail('Add at least one menu item.');while($nav->firstChild)$nav->removeChild($nav->firstChild);foreach(menu_nodes($doc,$items) as $node)$nav->appendChild($node);$source=serialize_doc($doc);$updates=[];foreach(pages_list() as $page)if($page['status']==='published')$updates[$page['slug']]=replace_shared(file_get_contents(page_file($page['slug'])),$source,true,false);write_transaction($updates);return ['pages'=>pages_list(),'page'=>page_get('index')];});}
function settings_get(): array {$mail=require CMS_ROOT.'/settings.php';return ['siteName'=>load_data(CMS_DATA.'/preferences.php',['siteName'=>'Next Chapter Collective'])['siteName'],'recipient_email'=>$mail['recipient_email']??'','sender_email'=>$mail['sender_email']??'','username'=>user_record()['username']??''];}
function settings_save(array $input): array {return locked(function()use($input){$name=text_value($input,'siteName',120);if($name==='')fail('Enter the site name.');$mail=[];foreach(['recipient_email','sender_email'] as $key){$v=text_value($input,$key,254);if($v!==''&&!filter_var($v,FILTER_VALIDATE_EMAIL))fail('Enter a valid email address.');$mail[$key]=$v;}atomic_write(CMS_ROOT.'/settings.php',"<?php\nreturn ".var_export($mail,true).";\n",0600);save_data(CMS_DATA.'/preferences.php',['siteName'=>$name]);return ['settings'=>settings_get()];});}
